CREATE TABLE IF NOT EXISTS market_candles (instrument_id text NOT NULL, interval text NOT NULL, start_ts timestamptz NOT NULL, open numeric NOT NULL, high numeric NOT NULL, low numeric NOT NULL, close numeric NOT NULL, volume numeric NOT NULL DEFAULT 0, PRIMARY KEY(instrument_id, interval, start_ts));
CREATE TABLE IF NOT EXISTS decision_ledger (decision_id uuid PRIMARY KEY, opportunity_id uuid, market text NOT NULL, market_timestamp timestamptz NOT NULL, strategy text, market_state_hash text, asura_version text, strategy_version text, feature_version text, sentinel_version text, portfolio_governor_version text, inputs jsonb NOT NULL DEFAULT '{}', features jsonb NOT NULL DEFAULT '{}', scores jsonb NOT NULL DEFAULT '{}', decision text NOT NULL, reasons jsonb NOT NULL DEFAULT '[]', rejections jsonb NOT NULL DEFAULT '[]', execution_intent jsonb, outcome jsonb);
CREATE TABLE IF NOT EXISTS journal_entries (id uuid PRIMARY KEY, opportunity_id uuid, created_at timestamptz NOT NULL DEFAULT now(), thesis jsonb, evidence jsonb, strategy text, selected_option jsonb, sentinel_decision jsonb, portfolio_decision jsonb, entry jsonb, exit jsonb, outcome jsonb, notes text);
